-- INPUT supabase/migrations/20261101500000_openfolk_client_information.sql
-- Explicit audited operator reads. No client RLS changes, provider calls or writes
-- to source records. Collection/column choices are server-owned allowlists.

create function public.openfolk_client_information(
 p_tenant uuid,p_collection text,p_reason text,p_after uuid default null,p_record uuid default null
) returns jsonb language plpgsql security definer set search_path=pg_catalog as $$
declare
 tab text; cols text[]; body text; result jsonb; entries jsonb; next_id uuid;
 audit_id uuid:=gen_random_uuid(); actor uuid:=auth.uid(); checked timestamptz;
begin
 -- Admin is required for business content, even though this operation only reads.
 perform public.learn_operator_input_access(p_tenant,actor,true);
 if p_reason is null or length(btrim(p_reason)) not between 3 and 500
  or p_collection is null or (p_after is not null and p_record is not null) then
  raise exception 'operator_information_request_invalid' using errcode='22023';end if;
 case p_collection
 when 'customers' then tab:='customer_cards';cols:=array['title','summary','status','priority','person_id','company_id','owner_id','due_at','latest_activity_at','recommended_action','updated_at'];
 when 'contacts' then tab:='people';cols:=array['display_name','first_name','last_name','primary_email','primary_phone','company_id','address_text','postcode','verified','updated_at'];
 when 'companies' then tab:='companies';cols:=array['name','domain','phone','address_text','postcode','verified','updated_at'];
 when 'sites' then tab:='sites';cols:=array['label','source_system','external_id','company_id','person_id','address_text','postcode','verified','updated_at'];
 when 'jobs' then tab:='jobs';cols:=array['title','job_number','description','source_system','external_id','customer_person_id','customer_company_id','site_id','status','priority','value_pennies','created_date','booked_date','completed_date','verified','updated_at'];
 when 'emails' then tab:='email_messages';cols:=array['provider','provider_message_id','provider_thread_id','from_email','from_name','to_emails','cc_emails','subject','snippet','body_text','sent_at','received_at','direction','updated_at'];
 when 'calls' then tab:='phone_calls';cols:=array['provider','provider_call_id','linked_id','direction','from_number','to_number','started_at','duration_seconds','outcome','updated_at'];
 when 'recordings' then tab:='phone_recordings';cols:=array['provider','provider_recording_id','provider_call_id','linked_id','file_size','started_at','duration_seconds','updated_at'];
 when 'transcripts' then tab:='phone_transcripts';cols:=array['recording_id','transcript_text','language','status','model','updated_at'];
 when 'communications' then tab:='interactions';cols:=array['source_connector_id','source_type','source_table','source_id','interaction_type','direction','occurred_at','subject','summary','body_preview','status','processing_status','related_person_id','related_company_id','related_job_id','updated_at'];
 when 'business_sources' then tab:='learn_business_input_versions';cols:=array['provider','collection','external_id','connection_id','content_hash','first_seen_at'];
 else raise exception 'operator_information_collection_invalid' using errcode='22023';end case;
 -- Project explicit columns, never return metadata, raw messages, credentials,
 -- provider recording URLs or Storage paths. Large scalar fields disclose truncation.
 select string_agg(format('%L,to_jsonb(t.%I)',c,c),',') into body from unnest(cols)c;
 if p_collection='business_sources' then
  body:=body||',''source_type'',t.payload->''type'',''source_status'',t.payload->''status'',''property_reference'',coalesce(t.payload->''propertyID'',t.payload->''parentPropertyID''),''description'',t.payload->''description'',''name'',t.payload->''name'',''address_line_1'',t.payload->''addressLine1'',''address_line_2'',t.payload->''addressLine2'',''postcode'',t.payload->''postcode''';
 end if;
 execute format($query$
  with page as materialized(
   select t.id,jsonb_build_object(%s) fields from public.%I t
   where t.tenant_id=$1 and ($2::uuid is null or t.id>$2)
    and ($3::uuid is null or t.id=$3) order by t.id limit 26
  ), shown as(select * from page order by id limit 25), mapped as(
   select id,jsonb_build_object('id',id,'fields',(
    select jsonb_object_agg(key,case when jsonb_typeof(value)='string' then to_jsonb(left(value#>>'{}',6000))
      when length(value::text)>6000 then to_jsonb(left(value::text,6000)) else value end)
    from jsonb_each(fields)),
    'truncated_fields',(select coalesce(jsonb_agg(key order by key),'[]'::jsonb) from jsonb_each(fields)
     where case when jsonb_typeof(value)='string' then length(value#>>'{}') else length(value::text) end>6000)) entry
   from shown
  ) select coalesce((select jsonb_agg(entry order by id) from mapped),'[]'::jsonb),
   case when (select count(*) from page)>25 then (select id from shown order by id desc limit 1) end
 $query$,body,tab) into entries,next_id using p_tenant,p_after,p_record;
 if p_record is not null and jsonb_array_length(entries)<>1 then
  raise exception 'operator_information_unavailable' using errcode='42501';end if;
 -- Recheck current effective authority before the response, retaining real actor.
 perform public.learn_operator_input_access(p_tenant,actor,true);
 checked:=clock_timestamp();
 insert into public.controlplane_change_log(id,tenant_id,actor,action,resource_type,resource_id,after,reason,correlation_id,view_as_active,source)
 values(audit_id,p_tenant,actor::text,'client_information.read',p_collection,coalesce(p_record::text,p_tenant::text),
  jsonb_build_object('record_ids',(select coalesce(jsonb_agg(x->'id'),'[]'::jsonb) from jsonb_array_elements(entries)x),'after',p_after),
  btrim(p_reason),audit_id::text,false,'openfolk-client-information');
 perform set_config('response.headers','[{"Cache-Control":"no-store"}]',true);
 result:=jsonb_build_object('version','openfolk-client-information/1','tenant_id',p_tenant,'actor_id',actor,
  'collection',p_collection,'after',p_after,'record',p_record,'rows',entries,'next_after',next_id,
  'observed_at',checked,'audit_id',audit_id);
 return result;
end$$;
revoke all on function public.openfolk_client_information(uuid,text,text,uuid,uuid) from public,anon,service_role;
grant execute on function public.openfolk_client_information(uuid,text,text,uuid,uuid) to authenticated;

-- INPUT supabase/migrations/20261101510000_openfolk_business_review.sql
-- OpenFolk uses the existing reviewed source-to-card writers with its real actor.
-- Ordinary tenant review/import authority is unchanged. No data projection on install.

create function public.learn_business_review_authority(p_tenant uuid,p_actor uuid)
returns void language plpgsql security definer set search_path=pg_catalog as $$
declare context jsonb;begin
 context:=nullif(current_setting('openfolk.business_review',true),'')::jsonb;
 if auth.role()='authenticated' and auth.uid()=p_actor
  and context->>'tenant'=p_tenant::text and context->>'actor'=p_actor::text
  and length(btrim(context->>'reason')) between 3 and 1000 then
  perform public.learn_operator_input_access(p_tenant,p_actor,true);
  perform pg_advisory_xact_lock_shared(hashtextextended('learn-work-registry',0));
  perform pg_advisory_xact_lock(hashtextextended('learn-roster:'||p_tenant::text,0));
  -- Audit inside the authority check as well as the outer receipt: a context
  -- setting never provides an unaudited alternative to the ordinary authority.
  insert into public.controlplane_change_log(tenant_id,actor,action,resource_type,resource_id,reason,view_as_active,source)
  values(p_tenant,p_actor::text,'business_review.authorise','commusoft',p_tenant::text,
   btrim(context->>'reason'),false,'openfolk-business-review');
 else
  perform public.learn_import_batch_authority(p_tenant,p_actor);
 end if;
end$$;
revoke all on function public.learn_business_review_authority(uuid,uuid) from public,anon,authenticated,service_role;

-- Only the retained Commusoft review path changes; generic imports do not.
do $$declare signature text;d text;needle text:='public.learn_import_batch_authority(';begin
 foreach signature in array array[
  'public.learn_business_input_review_access(uuid,uuid)',
  'public.learn_commusoft_review_customer(uuid,uuid,uuid,text,uuid,text)',
  'public.learn_commusoft_work_batch(uuid,uuid,uuid,text,jsonb,text,boolean,uuid)',
  'public.learn_commusoft_work_batch_result(uuid,uuid)'
 ] loop
  d:=pg_get_functiondef(signature::regprocedure);
  if (length(d)-length(replace(d,needle,'')))<>length(needle) then
   raise exception 'business_review_authority_contract_changed';end if;
  execute replace(d,needle,'public.learn_business_review_authority(');
 end loop;
end$$;

create function public.openfolk_business_review(p_tenant uuid,p_action text,p_reason text,p_args jsonb)
returns jsonb language plpgsql security definer set search_path=pg_catalog as $$
declare actor uuid:=auth.uid();result jsonb;old_context text;allowed text[];audit uuid:=gen_random_uuid();begin
 perform public.learn_operator_input_access(p_tenant,actor,true);
 if p_reason is null or length(btrim(p_reason)) not between 3 and 1000
  or jsonb_typeof(p_args) is distinct from 'object' or octet_length(p_args::text)>65536
  or p_args->>'p_tenant' is distinct from p_tenant::text then
  raise exception 'operator_business_review_invalid' using errcode='22023';end if;
 allowed:=case p_action
  when 'learn_commusoft_review_connections' then array['p_tenant']
  when 'learn_commusoft_review_page' then array['p_tenant','p_connection','p_after','p_limit']
  when 'learn_commusoft_review_search' then array['p_tenant','p_connection','p_after','p_limit','p_search']
  when 'learn_commusoft_customer_candidates' then array['p_tenant','p_version','p_kind','p_search','p_after','p_limit']
  when 'learn_commusoft_contact_candidates' then array['p_tenant','p_version','p_kind','p_search','p_after','p_limit']
  when 'learn_commusoft_confirm_customer' then array['p_tenant','p_version','p_kind','p_target','p_reason']
  when 'learn_commusoft_work_review_page' then array['p_tenant','p_connection','p_kind','p_after','p_limit']
  when 'learn_commusoft_work_review_search' then array['p_tenant','p_connection','p_kind','p_after','p_limit','p_search']
  when 'learn_commusoft_work_batch_result' then array['p_tenant','p_request']
  when 'learn_commusoft_work_batch' then array['p_tenant','p_request','p_connection','p_kind','p_items','p_reason','p_cancel','p_expected_actor']
  when 'learn_commusoft_job_details' then array['p_tenant','p_connection','p_version']
 end;
 if allowed is null or not p_args ?& allowed
  or exists(select 1 from jsonb_object_keys(p_args)k where not k=any(allowed))
  or (p_args ? 'p_expected_actor' and p_args->>'p_expected_actor' is distinct from actor::text) then
  raise exception 'operator_business_review_action_invalid' using errcode='22023';end if;
 old_context:=current_setting('openfolk.business_review',true);
 perform set_config('openfolk.business_review',jsonb_build_object('tenant',p_tenant,'actor',actor,'reason',btrim(p_reason))::text,true);
 case p_action
  when 'learn_commusoft_review_connections' then result:=public.learn_commusoft_review_connections(p_tenant);
  when 'learn_commusoft_review_page' then result:=public.learn_commusoft_review_page(p_tenant,(p_args->>'p_connection')::uuid,p_args->>'p_after',(p_args->>'p_limit')::integer);
  when 'learn_commusoft_review_search' then result:=public.learn_commusoft_review_search(p_tenant,(p_args->>'p_connection')::uuid,p_args->>'p_search',p_args->>'p_after',(p_args->>'p_limit')::integer);
  when 'learn_commusoft_customer_candidates' then result:=public.learn_commusoft_customer_candidates(p_tenant,(p_args->>'p_version')::uuid,p_args->>'p_kind',p_args->>'p_search',(p_args->>'p_after')::uuid,(p_args->>'p_limit')::integer);
  when 'learn_commusoft_contact_candidates' then result:=public.learn_commusoft_contact_candidates(p_tenant,(p_args->>'p_version')::uuid,p_args->>'p_kind',p_args->>'p_search',(p_args->>'p_after')::uuid,(p_args->>'p_limit')::integer);
  when 'learn_commusoft_confirm_customer' then result:=public.learn_commusoft_confirm_customer(p_tenant,(p_args->>'p_version')::uuid,p_args->>'p_kind',(p_args->>'p_target')::uuid,p_args->>'p_reason');
  when 'learn_commusoft_work_review_page' then result:=public.learn_commusoft_work_review_page(p_tenant,(p_args->>'p_connection')::uuid,p_args->>'p_kind',p_args->>'p_after',(p_args->>'p_limit')::integer);
  when 'learn_commusoft_work_review_search' then result:=public.learn_commusoft_work_review_search(p_tenant,(p_args->>'p_connection')::uuid,p_args->>'p_kind',p_args->>'p_search',p_args->>'p_after',(p_args->>'p_limit')::integer);
  when 'learn_commusoft_work_batch_result' then result:=public.learn_commusoft_work_batch_result(p_tenant,(p_args->>'p_request')::uuid);
  when 'learn_commusoft_work_batch' then result:=public.learn_commusoft_work_batch(p_tenant,(p_args->>'p_request')::uuid,(p_args->>'p_connection')::uuid,p_args->>'p_kind',p_args->'p_items',p_args->>'p_reason',(p_args->>'p_cancel')::boolean,(p_args->>'p_expected_actor')::uuid);
  when 'learn_commusoft_job_details' then result:=public.learn_commusoft_job_details(p_tenant,(p_args->>'p_connection')::uuid,(p_args->>'p_version')::uuid);
 end case;
 perform public.learn_operator_input_access(p_tenant,actor,true);
 insert into public.controlplane_change_log(id,tenant_id,actor,action,resource_type,resource_id,after,reason,correlation_id,view_as_active,source)
 values(audit,p_tenant,actor::text,'business_review.result',p_action,p_tenant::text,
  jsonb_build_object('version_id',p_args->'p_version','request_id',p_args->'p_request',
   'entity_id',result->'entity_id','card_id',result->'card_id','batch_id',result->'batch_id',
   'row_count',case when jsonb_typeof(result->'rows')='array' then jsonb_array_length(result->'rows') end),
  btrim(p_reason),audit::text,false,'openfolk-business-review');
 perform set_config('openfolk.business_review',coalesce(old_context,''),true);
 perform set_config('response.headers','[{"Cache-Control":"no-store"}]',true);
 return jsonb_build_object('version','openfolk-business-review/1','tenant_id',p_tenant,'actor_id',actor,
  'action',p_action,'audit_id',audit,'observed_at',clock_timestamp(),'result',result);
end$$;
revoke all on function public.openfolk_business_review(uuid,text,text,jsonb) from public,anon,service_role;
grant execute on function public.openfolk_business_review(uuid,text,text,jsonb) to authenticated;

-- INPUT supabase/migrations/20261101520000_learn_customer_business_context.sql
-- Provider-neutral canonical business context; no projection, capture or source writes.

create function public.learn_customer_business_context(
 p_tenant uuid,p_card uuid,p_collection text,p_after uuid default null,p_operator_reason text default null
) returns jsonb language plpgsql security definer set search_path=pg_catalog as $$
declare actor uuid:=auth.uid(); customer public.customer_cards%rowtype;
 tab text;cols text[];body text;predicate text;entries jsonb;next_id uuid;total bigint;
 audit uuid;checked timestamptz;operator_mode boolean:=p_operator_reason is not null;
begin
 if auth.role() is distinct from 'authenticated' or actor is null then
  raise exception 'customer_context_forbidden' using errcode='42501';end if;
 if operator_mode then
  perform public.learn_operator_input_access(p_tenant,actor,true);
  if length(btrim(p_operator_reason)) not between 3 and 500 then
   raise exception 'customer_context_reason_invalid' using errcode='22023';end if;
 else
  perform public.learn_import_batch_authority(p_tenant,actor);
 end if;
 select * into customer from public.customer_cards where tenant_id=p_tenant and id=p_card;
 if not found then raise exception 'customer_context_unavailable' using errcode='42501';end if;
 case p_collection
 when 'sites' then
  tab:='sites';cols:=array['label','address_text','postcode','verified','source_system','external_id','updated_at'];
  predicate:='(($3 is not null and t.person_id=$3) or ($3 is null and $4 is not null and t.company_id=$4))';
 when 'jobs' then
  tab:='jobs';cols:=array['title','job_number','description','status','priority','site_id','verified','source_system','external_id','created_date','completed_date','updated_at'];
  predicate:='(($3 is not null and t.customer_person_id=$3) or ($3 is null and $4 is not null and t.customer_company_id=$4))';
 when 'contacts' then
  tab:='people';cols:=array['display_name','primary_email','primary_phone','verified','updated_at'];
  predicate:='(t.id=$3 or ($3 is null and $4 is not null and t.company_id=$4) or exists(
   select 1 from public.graph_edges e join public.graph_nodes f on f.id=e.from_node_id and f.tenant_id=e.tenant_id
   join public.graph_nodes dest on dest.id=e.to_node_id and dest.tenant_id=e.tenant_id
   where e.tenant_id=$1 and e.edge_type=''contact_for'' and e.status=''active''
    and f.node_type=''person'' and f.status=''active'' and f.source_table=''people'' and f.source_id=t.id
    and dest.node_type=''customer_card'' and dest.status=''active'' and dest.source_table=''customer_cards'' and dest.source_id=$5))';
 else raise exception 'customer_context_collection_invalid' using errcode='22023';end case;
 select string_agg(format('%L,to_jsonb(t.%I)',c,c),',') into body from unnest(cols)c;
 if p_collection='jobs' then body:=body||',''time_evidence'',(select jsonb_object_agg(k,jsonb_build_object(
  ''state'',left(t.metadata#>>array[''learn_business_input'',''timestamps'',k,''state''],32),
  ''source'',left(t.metadata#>>array[''learn_business_input'',''timestamps'',k,''source''],100),
  ''instant'',left(t.metadata#>>array[''learn_business_input'',''timestamps'',k,''instant''],50)))
  from unnest(array[''created'',''completed''])k)';end if;
 execute format($query$
  with matched as materialized(
   select t.id,jsonb_build_object(%s) fields from public.%I t where t.tenant_id=$1 and %s
  ),page as(select * from matched where $2::uuid is null or id>$2 order by id limit 26),
  shown as(select * from page order by id limit 25),mapped as(
   select s.id,jsonb_build_object('id',s.id,'fields',(
    select jsonb_object_agg(key,case when jsonb_typeof(value)='string' then to_jsonb(left(value#>>'{}',4000)) else value end)
    from jsonb_each(s.fields)),
    'truncated_fields',(select coalesce(jsonb_agg(key order by key),'[]'::jsonb) from jsonb_each(s.fields)
      where jsonb_typeof(value)='string' and length(value#>>'{}')>4000),
    'sources',(select coalesce(jsonb_agg(x.entry order by x.link_id),'[]'::jsonb) from(
     select l.id link_id,jsonb_build_object('provider',l.provider,'collection',l.collection,'external_id',l.external_id,
      'version_id',v.id,'first_seen_at',v.first_seen_at) entry
     from public.learn_business_input_links l join public.learn_business_input_versions v
      on v.id=l.source_version_id and v.tenant_id=l.tenant_id and v.connection_id=l.connection_id
       and v.provider=l.provider and v.collection=l.collection and v.external_id=l.external_id
     where l.tenant_id=$1 and l.card_id=$5 and l.entity_table=%L and l.entity_id=s.id
     order by l.id limit 5)x)) entry from shown s
  ) select coalesce((select jsonb_agg(entry order by id) from mapped),'[]'::jsonb),
   case when (select count(*) from page)>25 then (select id from shown order by id desc limit 1) end,
   (select count(*) from matched)
 $query$,body,tab,predicate,tab) into entries,next_id,total
 using p_tenant,p_after,customer.person_id,customer.company_id,p_card;
 if operator_mode then
  perform public.learn_operator_input_access(p_tenant,actor,true);
  audit:=gen_random_uuid();
  insert into public.controlplane_change_log(id,tenant_id,actor,action,resource_type,resource_id,after,reason,correlation_id,view_as_active,source)
  values(audit,p_tenant,actor::text,'customer_context.read',p_collection,p_card::text,
   jsonb_build_object('record_ids',(select coalesce(jsonb_agg(x->'id'),'[]'::jsonb) from jsonb_array_elements(entries)x),'after',p_after),
   btrim(p_operator_reason),audit::text,false,'learn-customer-business-context');
 else perform public.learn_import_batch_authority(p_tenant,actor);end if;
 checked:=clock_timestamp();
 perform set_config('response.headers','[{"Cache-Control":"no-store"}]',true);
 return jsonb_build_object('version','learn-customer-business-context/1','tenant_id',p_tenant,'actor_id',actor,
  'card_id',p_card,'collection',p_collection,'after',p_after,'rows',entries,'next_after',next_id,'total',total,
  'observed_at',checked,'audit_id',audit,'operator_mode',operator_mode);
end$$;
revoke all on function public.learn_customer_business_context(uuid,uuid,text,uuid,text) from public,anon,service_role;
grant execute on function public.learn_customer_business_context(uuid,uuid,text,uuid,text) to authenticated;

-- INPUT supabase/migrations/20261101530000_learn_operator_phone_playback.sql
-- Explicit selected-client operator audio access; no tenant impersonation or new grants.

create function public.learn_operator_phone_recordings_read(p_tenant uuid,p_table text,p_id uuid,p_reason text,p_after uuid default null)
returns jsonb language plpgsql security definer set search_path=pg_catalog as $$
declare actor uuid:=auth.uid();available boolean;call_provider text;call_ref text;rows jsonb;more boolean;last_id uuid;audit uuid:=gen_random_uuid();
begin
 perform public.learn_operator_input_access(p_tenant,actor,true);
 if p_reason is null or length(btrim(p_reason)) not between 3 and 500 then raise exception 'phone_operator_reason_invalid' using errcode='22023';end if;
 if p_table is null or p_table not in ('phone_calls','phone_recordings') or p_id is null then raise exception 'phone_source_invalid' using errcode='22023';end if;
 if p_table='phone_calls' then
  select provider,provider_call_id into call_provider,call_ref from public.phone_calls where tenant_id=p_tenant and id=p_id;available:=found;
 else select exists(select 1 from public.phone_recordings where tenant_id=p_tenant and id=p_id) into available;end if;
 if not available then raise exception 'phone_source_unavailable' using errcode='42501';end if;
 if p_after is not null and not exists(select 1 from public.phone_recordings r where r.tenant_id=p_tenant and r.id=p_after
  and ((p_table='phone_recordings' and r.id=p_id) or (p_table='phone_calls' and r.provider=call_provider and r.provider_call_id=call_ref)))
 then raise exception 'phone_recording_cursor_invalid' using errcode='22023';end if;
 with bounded as materialized(
  select r.id,r.started_at,r.duration_seconds,(r.storage_path is not null and r.storage_path<>'') as audio_stored
  from public.phone_recordings r where r.tenant_id=p_tenant and (p_after is null or r.id>p_after)
   and ((p_table='phone_recordings' and r.id=p_id) or (p_table='phone_calls' and r.provider=call_provider and r.provider_call_id=call_ref))
  order by r.id limit 31
 ),page as materialized(select * from bounded order by id limit 30)
 select coalesce((select jsonb_agg(to_jsonb(p) order by p.id) from page p),'[]'),(select count(*)>30 from bounded),(select id from page order by id desc limit 1)
 into rows,more,last_id;
 perform public.learn_operator_input_access(p_tenant,actor,true);
 insert into public.controlplane_change_log(id,tenant_id,actor,action,resource_type,resource_id,after,reason,correlation_id,view_as_active,source)
 values(audit,p_tenant,actor::text,'phone_recordings.read',p_table,p_id::text,
  jsonb_build_object('record_ids',(select coalesce(jsonb_agg(x->'id'),'[]') from jsonb_array_elements(rows)x),'after',p_after),
  btrim(p_reason),audit::text,false,'learn-operator-phone-playback');
 return jsonb_build_object('version','learn-phone-recordings/1','tenant_id',p_tenant,'actor_id',actor,'audit_id',audit,'operator_mode',true,
  'table',p_table,'id',p_id,'source_available',true,'rows',rows,'next_cursor',case when more then last_id else null end);
end $$;

create function public.learn_operator_phone_playback_authorize(p_tenant uuid,p_actor uuid,p_recording uuid,p_reason text,p_source_digest text default null,p_request uuid default null)
returns jsonb language plpgsql security definer set search_path=pg_catalog as $$
declare r public.phone_recordings%rowtype;fingerprint text;prior public.learn_phone_playback_audit%rowtype;
begin
 perform public.learn_operator_input_access(p_tenant,p_actor,true);
 if p_reason is null or length(btrim(p_reason)) not between 3 and 500 then raise exception 'phone_operator_reason_invalid' using errcode='22023';end if;
 if p_recording is null or (p_request is null)<>(p_source_digest is null) then raise exception 'phone_playback_invalid' using errcode='22023';end if;
 select * into r from public.phone_recordings where tenant_id=p_tenant and id=p_recording for share;
 if not found or r.storage_path is null or r.storage_path='' or r.storage_path not like p_tenant::text||'/%'
 then raise exception 'phone_playback_unavailable' using errcode='42501';end if;
 fingerprint:=encode(sha256(convert_to(jsonb_build_object('id',r.id,'tenant',r.tenant_id,'path',r.storage_path,'size',r.file_size)::text,'UTF8')),'hex');
 if p_request is not null then
  if p_source_digest is distinct from fingerprint then raise exception 'phone_playback_source_changed' using errcode='PT409';end if;
  perform pg_advisory_xact_lock(hashtextextended('phone-playback:'||p_request::text,0));
  select * into prior from public.learn_phone_playback_audit where id=p_request;
  if found then
   if prior.tenant_id<>p_tenant or prior.actor_id<>p_actor or prior.recording_id<>p_recording or prior.source_digest<>fingerprint
    or not exists(select 1 from public.controlplane_change_log where id=p_request and tenant_id=p_tenant and actor=p_actor::text
      and action='phone_recording.play' and resource_id=p_recording::text and reason=btrim(p_reason) and source='learn-operator-phone-playback')
    then raise exception 'phone_playback_request_conflict' using errcode='PT409';end if;
  else
   insert into public.learn_phone_playback_audit(id,tenant_id,actor_id,recording_id,source_digest) values(p_request,p_tenant,p_actor,p_recording,fingerprint);
   insert into public.controlplane_change_log(id,tenant_id,actor,action,resource_type,resource_id,after,reason,correlation_id,view_as_active,source)
   values(p_request,p_tenant,p_actor::text,'phone_recording.play','phone_recordings',p_recording::text,jsonb_build_object('source_digest',fingerprint),btrim(p_reason),p_request::text,false,'learn-operator-phone-playback');
  end if;
 end if;
 perform public.learn_operator_input_access(p_tenant,p_actor,true);
 return jsonb_build_object('version','learn-phone-playback-target/1','tenant_id',p_tenant,'actor_id',p_actor,'operator_mode',true,'recording_id',p_recording,'storage_path',r.storage_path,'source_digest',fingerprint,'request_id',p_request);
end $$;
revoke all on function public.learn_operator_phone_recordings_read(uuid,text,uuid,text,uuid),public.learn_operator_phone_playback_authorize(uuid,uuid,uuid,text,text,uuid) from public,anon,authenticated,service_role;
grant execute on function public.learn_operator_phone_recordings_read(uuid,text,uuid,text,uuid),public.learn_operator_phone_playback_authorize(uuid,uuid,uuid,text,text,uuid) to authenticated;

insert into of_learn_deploy.migrations values('learn_operator_context_v1',current_setting('serviceos.release_source_sha256'),'tgbnakbxwcqjeimygroz',clock_timestamp());
notify pgrst,'reload schema';
commit;
